-- ADR0034. Pinned Unicode17 recipient repertoire and Ecuador phone metadata match shared/validation/person-rules.json v2.
-- No historical-data cleanup, constraint validation scan or replacement of the general ISO helper.
CREATE OR REPLACE FUNCTION pliego.fn_normalize_phone(p_value TEXT) RETURNS VARCHAR
LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER AS $$
DECLARE v_value TEXT;
BEGIN
    v_value:=btrim(regexp_replace(p_value,'[    -   　]',' ','g'),E' \t\n\r\f\x0b');
    IF v_value='' THEN RETURN NULL; END IF;
    IF v_value COLLATE "C" !~ '^[+0-9 ().\-\t\n\r]+$' THEN PERFORM pliego.fn_raise_domain_error('P1001','INVALID_ARGUMENT','Invalid phone characters'); END IF;
    v_value:=regexp_replace(v_value,E'[ ().\\-\t\n\r]','','g');
    IF v_value COLLATE "C" !~ '^\+593(?:[2-7][2-7]\d{6}|964[0-2]\d{5}|9(?:39|[57][89]|6[0-36-9]|[89]\d)\d{6})$' THEN PERFORM pliego.fn_raise_domain_error('P1001','INVALID_ARGUMENT','Teléfono de Ecuador inválido: usa +593 con un celular de 9 dígitos o fijo de 8 dígitos'); END IF;
    RETURN v_value;
END; $$;

CREATE FUNCTION pliego.fn_is_address_recipient(p_value TEXT) RETURNS BOOLEAN
