-- Validate only inserted or changed contact data; old stored values are not rewritten.
CREATE FUNCTION pliego.fn_validate_ec_customer_phone() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
 IF TG_OP='INSERT' OR NEW.telefono IS DISTINCT FROM OLD.telefono THEN
  NEW.telefono:=pliego.fn_normalize_phone(NEW.telefono);
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER trg_customer_ec_phone_validation BEFORE INSERT OR UPDATE OF telefono ON pliego.cliente
FOR EACH ROW EXECUTE FUNCTION pliego.fn_validate_ec_customer_phone();

CREATE FUNCTION pliego.fn_validate_ec_delivery_contact() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
 IF TG_OP='INSERT' OR NEW.destinatario IS DISTINCT FROM OLD.destinatario THEN
  NEW.destinatario:=pliego.fn_normalize_person_name(NEW.destinatario);
  IF NOT pliego.fn_is_address_recipient(NEW.destinatario) THEN
   PERFORM pliego.fn_raise_domain_error('P1001','INVALID_ARGUMENT','El destinatario solo puede contener letras, espacios, apóstrofes y guiones');
  END IF;
 END IF;
 IF TG_OP='INSERT' OR NEW.pais_codigo IS DISTINCT FROM OLD.pais_codigo THEN
  IF pliego.fn_normalize_country_code(NEW.pais_codigo) IS DISTINCT FROM 'EC' THEN
   PERFORM pliego.fn_raise_domain_error('P1001','INVALID_ARGUMENT','Las entregas están disponibles únicamente en Ecuador');
  END IF;
  NEW.pais_codigo:='EC';
 END IF;
 IF TG_OP='INSERT' OR NEW.telefono IS DISTINCT FROM OLD.telefono THEN
  NEW.telefono:=pliego.fn_normalize_phone(NEW.telefono);
  IF NEW.telefono IS NULL THEN PERFORM pliego.fn_raise_domain_error('P1001','INVALID_ARGUMENT','Escribe un teléfono de contacto'); END IF;
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER trg_address_ec_contact_validation BEFORE INSERT OR UPDATE OF destinatario,pais_codigo,telefono ON pliego.direccion
FOR EACH ROW EXECUTE FUNCTION pliego.fn_validate_ec_delivery_contact();
-- A previously stored foreign address cannot create a NEW out-of-scope delivery snapshot.
-- Existing append-only snapshots, invoices and ISO reference validation remain unchanged.
CREATE TRIGGER trg_order_address_ec_contact_validation BEFORE INSERT ON pliego.pedido_direccion
FOR EACH ROW EXECUTE FUNCTION pliego.fn_validate_ec_delivery_contact();
